export function shaText(s){return createHash('sha256').update(s).digest('hex').toUpperCase()}
export async function shaFile(p){return await new Promise((res,rej)=>{const h=createHash('sha256'); createReadStream(p).on('data',d=>h.update(d)).on('error',rej).on('end',()=>res(h.digest('hex').toUpperCase()))})}
export async function verifySourceHash(source,expected){if(!existsSync(source)){const e=Error('SOURCE_UNAVAILABLE'); e.classification='SOURCE_UNAVAILABLE'; throw e;} const observed=await shaFile(source); if(observed.toUpperCase()!==expected.toUpperCase()){const e=Error('MANUFACTURING_FAILED:SOURCE_HASH_MISMATCH'); e.classification='MANUFACTURING_FAILED'; e.expected=expected; e.observed=observed; throw e;} return observed;}
export function extractionSql(source,outDir,release){const q=`COPY (SELECT id::VARCHAR AS source_id, COALESCE(names.primary, map_extract_value(names.common, 'en'))::VARCHAR AS display_name, names.primary::VARCHAR AS primary_name, map_extract_value(names.common, 'en')::VARCHAR AS common_name_en, categories.primary::VARCHAR AS primary_category, list_sort(list_distinct(list_filter(categories.alternate, x -> x IS NOT NULL))) AS alternate_categories, brand.names.primary::VARCHAR AS brand_primary, map_extract_value(brand.names.common, 'en')::VARCHAR AS brand_common_name, brand.wikidata::VARCHAR AS brand_wikidata, NULLIF(TRIM(COALESCE(list_extract(addresses,1).freeform,'')), '') AS formatted_address, list_extract(addresses,1).locality::VARCHAR AS source_locality, list_extract(addresses,1).postcode::VARCHAR AS postcode, list_extract(addresses,1).region::VARCHAR AS region, list_extract(addresses,1).country::VARCHAR AS country, list_count(addresses) AS source_address_count, 'FIRST_AVAILABLE'::VARCHAR AS selected_address_method, confidence::DOUBLE AS confidence, 'UNKNOWN'::VARCHAR AS lifecycle, ST_X(geometry)::DOUBLE AS longitude, ST_Y(geometry)::DOUBLE AS latitude, '${release}'::VARCHAR AS source_release, printf('part-%02x', hash(id::VARCHAR) % ${PARTITION_COUNT}) AS partition_key FROM read_parquet('${source.replaceAll("'","''")}') WHERE geometry IS NOT NULL AND COALESCE(names.primary, map_extract_value(names.common, 'en')) IS NOT NULL ORDER BY partition_key, source_id) TO '${outDir.replaceAll("'","''")}' (FORMAT PARQUET, PARTITION_BY (partition_key), OVERWRITE_OR_IGNORE);`; return q;}
export async function runDuckDbDirect({duckdbPath,sql,logDir}){mkdirSync(logDir,{recursive:true}); const sqlPath=join(logDir,'lp1601f-extraction.sql'); writeFileSync(sqlPath,sql); const out=createWriteStream(join(logDir,'duckdb.stdout.log')); const err=createWriteStream(join(logDir,'duckdb.stderr.log')); return await new Promise((res,rej)=>{const child=spawn(duckdbPath,['-c',`.read ${sqlPath}`],{stdio:['ignore','pipe','pipe']}); child.stdout.pipe(out); child.stderr.pipe(err); child.on('error',rej); child.on('close',code=>{out.end(); err.end(); code===0?res({exitCode:0,sqlPath,stdoutLog:out.path,stderrLog:err.path}):rej(Object.assign(Error('MANUFACTURING_FAILED:DUCKDB_FAILED'),{exitCode:code,sqlPath}))})})}

export function counties(){const d=JSON.parse(readFileSync(abs('data/lp104/texas-counties.json'),'utf8')); return d.counties.map(c=>({county:`${c.countyName} County`,countyFips:c.fips,slug:c.countyId}))}
export function normalizeTexasCountyFips(value,{allowThreeDigitTexasCountyCode=false}={}){if(value==null) throw Error('MANUFACTURING_FAILED:INVALID_COUNTY_FIPS'); const s=String(value).trim(); if(/^48\d{3}$/.test(s)) return s; if(allowThreeDigitTexasCountyCode&&/^\d{3}$/.test(s)) return `48${s}`; throw Error('MANUFACTURING_FAILED:INVALID_COUNTY_FIPS');}
function bboxOfGeometry(g){let b=[Infinity,Infinity,-Infinity,-Infinity]; const scan=a=>Array.isArray(a[0])&&typeof a[0][0]==='number'?a.forEach(([x,y])=>{b=[Math.min(b[0],x),Math.min(b[1],y),Math.max(b[2],x),Math.max(b[3],y)]}):a.forEach(scan); scan(g.coordinates); return b;}
function pointInRing(x,y,ring){let inside=false; for(let i=0,j=ring.length-1;i<ring.length;j=i++){const xi=ring[i][0],yi=ring[i][1],xj=ring[j][0],yj=ring[j][1]; const on=((y-yi)*(xj-xi)===(x-xi)*(yj-yi))&&x>=Math.min(xi,xj)&&x<=Math.max(xi,xj)&&y>=Math.min(yi,yj)&&y<=Math.max(yi,yj); if(on) return 'BOUNDARY'; const inter=((yi>y)!==(yj>y))&&(x<(xj-xi)*(y-yi)/(yj-yi)+xi); if(inter) inside=!inside;} return inside?'INSIDE':'OUTSIDE';}
function pointInPolygonCoords(x,y,poly){let outer=pointInRing(x,y,poly[0]); if(outer==='BOUNDARY') return 'BOUNDARY'; if(outer!=='INSIDE') return 'OUTSIDE'; for(const hole of poly.slice(1)){const r=pointInRing(x,y,hole); if(r==='BOUNDARY') return 'BOUNDARY'; if(r==='INSIDE') return 'OUTSIDE';} return 'INSIDE';}
export function loadGovernedCountyGeometries(path=abs('assets/location-resolution/gridly-authoritative-texas-county-geometry-v1.json')){const raw=readFileSync(path); const d=JSON.parse(raw); const propertyNames=new Set(); const features=(d.counties||d.features||[]).map((f,i)=>{const props=f.properties||f; Object.keys(props).forEach(k=>propertyNames.add(k)); const fips=normalizeTexasCountyFips(props.GEOID??props.geoid??props.FIPS??props.fips??props.countyFips??props.fips_code); const name=props.displayName||props.countyName||props.name||props.sourceName; if(!name||/^Texas County/.test(name)) throw Error('MANUFACTURING_FAILED:PLACEHOLDER_COUNTY_NAMES'); if(!f.geometry) throw Error('MANUFACTURING_FAILED:INCOMPLETE_COUNTY_GEOMETRY'); return {countyFips:fips,countyName:/County$/.test(name)?name:`${name} County`,slug:(props.countyId||name.toLowerCase().replace(/ county$/i,'').replace(/[^a-z0-9]+/g,'-')).replace(/^-|-$/g,''),geometry:f.geometry,bbox:bboxOfGeometry(f.geometry)};}); const unique=new Set(features.map(f=>f.countyFips)); if(features.length!==254||unique.size!==254||features.some(f=>!f.countyFips.startsWith('48'))) throw Error('MANUFACTURING_FAILED:INCOMPLETE_COUNTY_GEOMETRY'); return {sourcePath:path,sourceSha256:createHash('sha256').update(raw).digest('hex').toUpperCase(),propertyNames:[...propertyNames].sort(),selectedFipsProperty:'fips',features};}
let COUNTY_GEOMS=null; function countyGeoms(){return COUNTY_GEOMS ||= loadGovernedCountyGeometries();}

