export async function verifyLp1601f(){const required=Object.values(P1601F); for(const p of required){if(!existsSync(abs(p))) throw Error(`LP1601F_VERIFY_MISSING:${p}`);} const manifest=JSON.parse(await import('node:fs/promises').then(fs=>fs.readFile(abs(P1601F.candidateManifest),'utf8'))); if((manifest.counties||[]).length!==254) throw Error('LP1601F_VERIFY_COUNTY_COUNT'); const mem=JSON.parse(await import('node:fs/promises').then(fs=>fs.readFile(abs(P1601F.memory),'utf8'))); if(mem.fullSourceStringCreated!==false||mem.fullRegistryArrayCreated!==false) throw Error('LP1601F_VERIFY_MEMORY_FLAGS'); return {schemaVersion:'gridly.lp1601f.verification.v1',status:'PASS',writesPerformed:false,networkCallsPerformed:false,counties:254,runtimeUnchanged:true,deploymentUnauthorized:true,activationUnauthorized:true};}

