export function parseLp1601gArgs(argv=process.argv.slice(2)){const out={write:false,controlledTestFixture:false,unknown:[]}; for(let i=0;i<argv.length;i++){const a=argv[i]; if(FLAGS.has(a)){if(a==='--write') out.write=true; if(a==='--controlled-test-fixture') out.controlledTestFixture=true; continue;} if(VALUES.has(a)){if(i+1>=argv.length||argv[i+1].startsWith('--')) throw Error(`LP1601G_MISSING_VALUE:${a}`); out[a.slice(2).replace(/-([a-z])/g,(_,c)=>c.toUpperCase())]=argv[++i]; continue;} if(a.startsWith('--')) out.unknown.push(a); else out.unknown.push(a);} if(out.unknown.length) throw Error(`LP1601G_UNKNOWN_ARGUMENT:${out.unknown.join(',')}`); return out;}
function redactedPath(p){return p?{supplied:true,fileName:basename(p),absolute:/^(?:[A-Za-z]:\\|\/)/.test(p),sha256:shaText(p).slice(0,16)}:{supplied:false};}
export async function inspectSource(source){if(!source) return {exists:false,readable:false,size:null,magic:null,format:null}; try{const st=statSync(source); const fd=await import('node:fs/promises').then(fs=>fs.open(source,'r')); const b=Buffer.alloc(4); await fd.read(b,0,4,0); await fd.close(); const magic=b.toString('utf8'); return {exists:true,readable:true,size:st.size,magic,format:['.parquet','.geoparquet'].some(x=>source.toLowerCase().endsWith(x))?'GeoParquet':'UNSUPPORTED'};}catch{return {exists:existsSync(source),readable:false,size:existsSync(source)?statSync(source).size:null,magic:null,format:null};}}
export async function selectManufacturingMode(args){const src=await inspectSource(args.source); if(args.controlledTestFixture||args.source===CONTROLLED_TEST_FIXTURE) return {mode:CONTROLLED_TEST_FIXTURE,source:src,reason:'labeled controlled test fixture'}; if(!args.source||!src.exists||!src.readable) return {mode:SOURCE_UNAVAILABLE,source:src,reason:'explicit source missing or unreadable'}; if(args.expectedSha256&&args.write&&args.duckdbPath&&src.format==='GeoParquet') return {mode:OWNER_SOURCE,source:src,reason:'owner source preconditions supplied'}; return {mode:'MANUFACTURING_FAILED',source:src,reason:'required owner-source arguments incomplete'};}
