function fileFormat(p){const l=p.toLowerCase(); if(l.endsWith('.jsonl.gz')) return 'jsonl.gz'; if(l.endsWith('.jsonl')) return 'jsonl'; if(l.endsWith('.geoparquet')) return 'geoparquet'; if(l.endsWith('.parquet')) return 'parquet'; return null;}
