export function parseDuckDbScalarCount(stdout){const s=String(stdout||'').trim(); if(!s) throw Error('MANUFACTURING_FAILED:ROW_COUNT_PARSE_EMPTY'); try{const j=JSON.parse(s); if(Array.isArray(j)){const v=j[0]?.row_count??j[0]?.total_source_rows??Object.values(j[0]||{})[0]; if(Number.isSafeInteger(Number(v))) return Number(v);} if(Number.isSafeInteger(Number(j))) return Number(j);}catch{} const first=s.split(/\r?\n/).map(x=>x.trim()).filter(Boolean).find(x=>/^\d+$/.test(x)||/^"?\d+"?(?:,|$)/.test(x)); if(first){const n=Number(first.replace(/"/g,'').split(',')[0]); if(Number.isSafeInteger(n)) return n;} throw Error('MANUFACTURING_FAILED:ROW_COUNT_PARSE_INVALID');}
