export async function verifyLp1601l(){for(const p of Object.values(P1601L)){if(!existsSync(abs(p))) throw Error(`LP1601L_VERIFY_MISSING:${p}`);} const geom=JSON.parse(readFileSync(abs(P1601L.geometry),'utf8')); if(geom.featureCount!==254||geom.uniqueFipsCount!==254) throw Error('LP1601L_VERIFY_GEOMETRY_COUNT'); const names=JSON.parse(readFileSync(abs(P1601L.names),'utf8')); if(names.authoritativeCountyNameCount!==254||names.placeholderCountyNameCount!==0) throw Error('LP1601L_VERIFY_COUNTY_NAMES'); const rec=JSON.parse(readFileSync(abs(P1601L.reconcile),'utf8')); if(rec.status!=='PASS') throw Error('LP1601L_VERIFY_RECONCILIATION'); const paths=JSON.parse(readFileSync(abs(P1601L.paths),'utf8')); if(paths.pathCollisionCount!==0) throw Error('LP1601L_VERIFY_PATH_COLLISION'); const liberty=assignLp1601jCounty(-94.8,30.05); if(liberty.countyFips!=='48291') throw Error('LP1601L_VERIFY_LIBERTY_REGRESSION'); return {schemaVersion:'gridly.lp1601l.verification.v1',status:'PASS',writesPerformed:false,networkCallsPerformed:false,counties:254,runtimeUnchanged:true,deploymentUnauthorized:true,activationUnauthorized:true,protectedArtifactsUnchanged:true};}

